BTNode * insertBST (BTNode * root, int key) {
    if (root == NULL) {
        BTNode * newNode = createBTNode (key);
        return newNode;
    }
    if (key < root->data)
        root->left = insertBST (root->left, key);
    else
    if (key > root->data)
        root->right = insertBST (root->right, key);
    return root;
}

Node * merge (Node * top1, Node * top2) {
    if (top1 == NULL) return top2;
    if (top2 == NULL) return top1;
    if (top1->data <= top2->data) {
        top1->next = merge (top1->next, top2);
        return top1;
    }
    top2->next = merge (top1, top2->next);
    return top2;
}

